<section class="hero"><h1><?=e($heading)?></h1><p><?=e($description)?></p></section>
<section class="panel"><form class="filters" method="get"><label class="field">Biznesi / NRB<input name="q" value="<?=e($filters['q']??'')?>"></label><label class="field">Kodi NACE<input name="nace" value="<?=e($filters['nace']??'')?>"></label><label class="field">Klasifikimi<select name="classification"><option value="">Të gjitha</option><?php foreach(['UNCLASSIFIED'=>'Pa klasifikim','AUTO'=>'Automatik','MANUAL'=>'Manual','AMBIGUOUS'=>'I paqartë'] as $v=>$l):?><option value="<?=e($v)?>" <?=($filters['classification']??'')===$v?'selected':''?>><?=e($l)?></option><?php endforeach;?></select></label><label class="field">Statusi ATK<select name="atk_status"><option value="">Të gjitha</option><?php foreach(['ACTIVE'=>'Aktiv','DEACTIVATED'=>'Çaktivizuar','NEEDS_REVIEW'=>'Për shqyrtim'] as $v=>$l):?><option value="<?=e($v)?>" <?=($filters['atk_status']??'')===$v?'selected':''?>><?=e($l)?></option><?php endforeach;?></select></label><button>Kërko</button></form></section>
<div class="table-wrap"><table><thead><tr><th>Biznesi</th><th>NRB</th><th>NACE ARBK</th><th>ATK</th><th>Kategoria komunale</th><th>Tarifa</th><th></th></tr></thead><tbody><?php foreach($result['rows'] as $row):?><tr><td><strong><?=e($row['legal_name'])?></strong></td><td><?=e($row['registration_number'])?></td><td><?=e($row['arbk_nace_code'])?></td><td><span class="badge <?=e($row['atk_status'])?>"><?=e($row['atk_status'])?></span></td><td><?=e($row['nace_category']??'Pa klasifikim')?><?php if(!$row['nace_category'] && (int)$row['candidate_count']>1):?><br><span class="badge AMBIGUOUS"><?=e($row['candidate_count'])?> mundësi</span><?php endif;?></td><td><?=isset($row['applied_tariff'])?number_format((float)$row['applied_tariff'],2).' €':'—'?></td><td><a class="button secondary" href="<?=e(app_url('/public/admin/businesses/view.php?id='.(int)$row['business_id']))?>">Hap</a></td></tr><?php endforeach;?></tbody></table><?php if(!$result['rows']):?><div class="empty">Nuk u gjet asnjë biznes.</div><?php endif;?></div>
<div class="pagination"><span><?=number_format($result['total'])?> rezultate · Faqja <?=$result['page']?> / <?=$result['pages']?></span><span><?php if($result['page']>1):?><a href="?<?=e(http_build_query(array_merge($filters,['page'=>$result['page']-1])))?>">← Para</a><?php endif;?> <?php if($result['page']<$result['pages']):?><a href="?<?=e(http_build_query(array_merge($filters,['page'=>$result['page']+1])))?>">Pas →</a><?php endif;?></span></div>
